// One SSE connection per loaded browser page.

window.eventSource =
    new EventSource(
        "/events/stream/"
    );


window.eventSource.onopen = () => {
    console.log(
        "[SSE] Connection opened"
    );
};


window.eventSource.onerror = (
    error
) => {
    console.error(
        "[SSE] Connection error:",
        error
    );
};


// Heartbeats are generated by Django
// every 15 seconds when there are no
// other events.

window.eventSource.addEventListener(
    "heartbeat",
    (event) => {
        try {
            const data =
                JSON.parse(
                    event.data
                );

            console.log(
                "[SSE] Heartbeat:",
                data
            );
        } catch (error) {
            console.error(
                "[SSE] Could not parse heartbeat:",
                error
            );
        }
    }
);


// This is sent only after the
// ObservatoryEvent has been committed.

window.eventSource.addEventListener(
    "observatory_event_created",
    (event) => {
        let data;

        try {
            data = JSON.parse(
                event.data
            );
        } catch (error) {
            console.error(
                "[SSE] Could not parse "
                + "observatory event:",
                error
            );

            return;
        }

        console.log(
            "[SSE] Observatory event created:",
            data
        );

        document.body.dispatchEvent(
            new CustomEvent(
                "observatoryEventCreated",
                {
                    detail: data
                }
            )
        );
    }
);


// Close the SSE connection when
// navigating away.

window.addEventListener(
    "pagehide",
    () => {
        if (
            window.eventSource
        ) {
            window.eventSource.close();
        }
    }
);